// V16 exact local-collar exhaustive search for phase-3 |J|=3..4.
// Modes: default --strict requires W9 to stay exact at every phase; --endpoint-only
// permits temporary W damage and asks whether the full W9 prefix is restored at t=120.
// Pairword transition is exact. For P=H C rev(H), low normalized digit at i uses
// carry from H[0..i); the mirrored digit's carry is determined by the first non-9
// in H[i+1:] (gamma=0) or H[i:] (gamma=1). The phase-3 root fixes gamma_t. The
// untouched U3 tail has a non-9 in every 3 cells; the 120-step U-side cone bound
// is <=152 columns, so collar=170 is a sound local window with reset guard.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
using V=vector<int>;
struct Lattice{array<int,12>gamma{};array<V,12>W,B;};
Lattice load_lattice(const string&path){ifstream in(path);if(!in)throw runtime_error("cannot open "+path);int p,nb,m,b;in>>p>>nb>>m>>b;if(p!=12||nb!=34||m!=9||b!=10)throw runtime_error("bad lattice header");Lattice x;for(int&i:x.gamma)in>>i;for(auto&w:x.W){w.resize(9);for(int&z:w)in>>z;}for(int t=0;t<12;t++)for(int i=0;i<9;i++){int z;in>>z;}for(auto&v:x.B){v.resize(34);for(int&z:v)in>>z;}if(!in)throw runtime_error("truncated lattice");return x;}
V make_u(int a,int r){V b{9,a,18-a};return{b[r%3],b[(r+1)%3],b[(r+2)%3]};}
V decode(uint64_t n,int len){V w(len);for(int&i:w){i=n%19;n/=19;}return w;}
bool starts(const V&a,const V&b){return a.size()>=b.size()&&equal(b.begin(),b.end(),a.begin());}
V prefix(const Lattice&x,int phase,int q){V p=x.B[phase];for(int i=0;i<q;i++)p.insert(p.end(),x.W[phase].begin(),x.W[phase].end());return p;}
V bulk_step(const V&w,int gamma){int m=w.size();V a(m+1),b(m+1);bool ok=false;for(int s=0;s<=1&&!ok;s++){a[0]=s;for(int i=0;i<m;i++)a[i+1]=(w[i]+a[i])/10;ok=a[m]==s;}if(!ok)throw runtime_error("no cyclic low carry");ok=false;for(int s=0;s<=1&&!ok;s++){b[m]=s;for(int i=m-1;i>=0;i--)b[i]=(w[i]+b[i+1])/10;ok=b[0]==s;}if(!ok)throw runtime_error("no cyclic high carry");V z(m);for(int i=0;i<m;i++){int lo=(w[i]+a[i])%10;int hi=gamma?((w[(i+m-1)%m]+b[i])%10):((w[i]+b[i+1])%10);z[i]=lo+hi;}return z;}
void local_step_into(const V&H,const V&U,int ustart,int gamma,V&low,V&high,V&out){int n=H.size();int state=-1;for(int j=0;j<3;j++){int x=U[(n+j-ustart)%3];if(x!=9){state=x>=10;break;}}if(state<0)throw runtime_error("U tail did not reset high carry");int c=0;for(int i=0;i<n;i++){int z=H[i]+c;low[i]=z%10;c=z/10;}for(int i=n-1;i>=0;i--){if(!gamma){high[i]=state;if(H[i]!=9)state=H[i]>=10;}else{if(H[i]!=9)state=H[i]>=10;high[i]=state;}}for(int i=0;i<n;i++){if(!gamma)out[i]=low[i]+((H[i]+high[i])%10);else if(i==0)out[i]=low[i]+1;else out[i]=low[i]+((H[i-1]+high[i])%10);}}
V initial_collar(const Lattice&x,int phase,int q,const V&J,const V&U,int collar){int root=34+9*q;int n=root+collar;V H(n);for(int i=0;i<34;i++)H[i]=x.B[phase][i];for(int i=34;i<root;i++)H[i]=x.W[phase][(i-34)%9];for(int i=root;i<root+(int)J.size();i++)H[i]=J[i-root];int us=root+(int)J.size();for(int i=us;i<n;i++)H[i]=U[(i-us)%3];return H;}
int main(int argc,char**argv){string lattice="calculation/decimal_frontier/lattice_kinks/data/lat_p12m9.txt";int q=14,k=100,phase0=3,steps=120,collar=170;uint64_t limit=UINT64_MAX,start=0;bool endpointOnly=false;for(int i=1;i<argc;i++){string a=argv[i];if(a=="--lattice"&&i+1<argc)lattice=argv[++i];else if(a=="--q"&&i+1<argc)q=stoi(argv[++i]);else if(a=="--k"&&i+1<argc)k=stoi(argv[++i]);else if(a=="--phase"&&i+1<argc)phase0=stoi(argv[++i]);else if(a=="--steps"&&i+1<argc)steps=stoi(argv[++i]);else if(a=="--collar"&&i+1<argc)collar=stoi(argv[++i]);else if(a=="--limit"&&i+1<argc)limit=stoull(argv[++i]);else if(a=="--start"&&i+1<argc)start=stoull(argv[++i]);else if(a=="--endpoint-only")endpointOnly=true;else{cerr<<"bad argument "<<a<<"\n";return 2;}}if(q<14||k<100||phase0<0||phase0>=12||steps!=120||collar<158)throw runtime_error("require q>=14, k>=100, exactly 120 steps, and collar >=158");Lattice x=load_lattice(lattice);vector<V>Us;for(int a=0;a<=18;a+=2)for(int r=0;r<3;r++)Us.push_back(make_u(a,r));sort(Us.begin(),Us.end());Us.erase(unique(Us.begin(),Us.end()),Us.end());if(Us.size()!=30)throw runtime_error("U count !=30");const uint64_t nJ3=19ULL*19*19,nJ4=19ULL*19*19*19,perJ=30,totalAll=(nJ3+nJ4)*perJ;uint64_t end=min(totalAll,start+limit),tested=0,survived=0,clockFail=0,everMismatchCount=0,restoredAfterDamage=0,sameCellPort=0;array<uint64_t,121>fail{};vector<string>samples;int rootLen=34+9*q,M=rootLen+collar;array<V,12>expected;for(int ph=0;ph<12;ph++)expected[ph]=prefix(x,ph,q);vector<array<V,121>>traj(Us.size());for(size_t ui=0;ui<Us.size();ui++){traj[ui][0]=Us[ui];for(int t=0;t<steps;t++)traj[ui][t+1]=bulk_step(traj[ui][t],x.gamma[(phase0+t)%12]);if(traj[ui][steps]!=Us[ui])throw runtime_error("U row fails 120-step return at this phase");}
for(uint64_t ix=start;ix<end;ix++){int len;uint64_t jc;int ui;if(ix<nJ3*perJ){len=3;jc=ix/perJ;ui=ix%perJ;}else{uint64_t y=ix-nJ3*perJ;len=4;jc=y/perJ;ui=y%perJ;}V J=decode(jc,len);const V&U0=Us[ui];int ustart=rootLen+len;V H=initial_collar(x,phase0,q,J,U0,collar),Q(M),low(M),high(M);bool ok=true,everMismatch=false;tested++;for(int t=0;t<steps;t++){int ph=(phase0+t)%12;int gamma=(H[0]>=10);if(gamma!=x.gamma[ph]){clockFail++;fail[t+1]++;ok=false;break;}local_step_into(H,traj[ui][t],ustart,gamma,low,high,Q);int nph=(ph+1)%12;if(!starts(Q,expected[nph])){if(!everMismatch)fail[t+1]++;everMismatch=true;if(!endpointOnly){ok=false;break;}}H.swap(Q);}if(ok){if(endpointOnly){if(everMismatch)everMismatchCount++;if(starts(H,expected[phase0])){survived++;if(everMismatch)restoredAfterDamage++;string detail="J=";for(int z:J)detail+=to_string(z)+",";detail+=" U=";for(int z:U0)detail+=to_string(z)+",";for(int candLen:{3,4}){bool uok=true;for(int z=0;z<30;z++)if(H[rootLen+candLen+z]!=U0[z%3]){uok=false;break;}if(uok){sameCellPort++;detail+=" Jprime=";for(int z=0;z<candLen;z++)detail+=to_string(H[rootLen+z])+",";detail+=" U-port=PASS(len="+to_string(candLen)+")";break;}}if(samples.size()<100)samples.push_back(detail);}}else{survived++;if(samples.size()<20){string s="J=";for(int z:J)s+=to_string(z)+",";s+=" U=";for(int z:U0)s+=to_string(z)+",";samples.push_back(s);}}}}
cout<<"lane="<<(endpointOnly?"endpoint-only-W9":"strict-per-phase-W9")<<" phase="<<phase0<<" q="<<q<<" k="<<k<<" steps="<<steps<<" collar="<<collar<<"\n";cout<<"U_count="<<Us.size()<<" J_count="<<(nJ3+nJ4)<<" total_domain="<<totalAll<<" range=["<<start<<","<<end<<") tested="<<tested<<"\n";cout<<"survivors="<<survived<<" clock_failures="<<clockFail<<"\n";if(endpointOnly)cout<<"candidates_with_temporary_W_mismatch="<<everMismatchCount<<" endpoint_restored_after_damage="<<restoredAfterDamage<<" same_cell_seam_Uport_candidates="<<sameCellPort<<"\n";for(int t=1;t<=steps;t++)if(fail[t])cout<<"first_mismatch_or_clock_fail["<<t<<"]="<<fail[t]<<"\n";for(auto&s:samples)cout<<"sample "<<s<<"\n";if(start!=0||end!=totalAll)cout<<"PARTIAL RANGE: no exhaustion claim.\n";else if(endpointOnly)cout<<"FINITE-DOMAIN COMPLETE for endpoint-only W9 restoration lane; see CELL_REPORT.md for centre independence and phase-rotated all-width insertion proof.\n";else cout<<"FINITE-DOMAIN COMPLETE for strict-per-phase-W9 lane; see CELL_REPORT.md for the phase-rotated all-width insertion argument.\n";}
